            "synthetic": true,
            "source_namespace": "roadshow_demo",
            "verbatim": false,
            "text": "整理口头任务到成果回流的展示范围。围绕目标、来源、本人核对与成果回流写出讲述说明，列明已有能力和仍需接入的环节。",
