            "synthetic": true,
            "source_namespace": "roadshow_demo",
            "verbatim": false,
            "text": "核对最终作品与答辩材料的提交要求。参照本聊天提供的提交说明核对本地PPT、在线HTML、功能录屏与源码材料。",
