            "demo": true,
            "synthetic": true,
            "source_namespace": "roadshow_demo",
            "verbatim": false,
            "text": "跟进选手群里的关键通知与文档。按通知更新时间整理关键文档、截止时间与提交要求，保留需要继续核对的事项。",
